import{_ as c,r as e,o as i,c as l,e as t,a as n,d as a,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Basic Usage - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuration","slug":"configuration","link":"#configuration","children":[{"level":3,"title":"Read / Write Connections","slug":"read-write-connections","link":"#read-write-connections","children":[]}]},{"level":2,"title":"Running Raw SQL Queries","slug":"running-raw-sql-queries","link":"#running-raw-sql-queries","children":[{"level":4,"title":"Running a select query","slug":"running-a-select-query","link":"#running-a-select-query","children":[]},{"level":4,"title":"Using named bindings","slug":"using-named-bindings","link":"#using-named-bindings","children":[]},{"level":4,"title":"Running an insert statement","slug":"running-an-insert-statement","link":"#running-an-insert-statement","children":[]},{"level":4,"title":"Running an update statement","slug":"running-an-update-statement","link":"#running-an-update-statement","children":[]},{"level":4,"title":"Running a delete statement","slug":"running-a-delete-statement","link":"#running-a-delete-statement","children":[]},{"level":4,"title":"Running a general statement","slug":"running-a-general-statement","link":"#running-a-general-statement","children":[]}]},{"level":2,"title":"Multiple Database Connections","slug":"multiple-database-connections","link":"#multiple-database-connections","children":[]},{"level":2,"title":"Database Transactions","slug":"database-transactions","link":"#database-transactions","children":[{"level":4,"title":"Manually using transactions","slug":"manually-using-transactions","link":"#manually-using-transactions","children":[]}]},{"level":2,"title":"Database Events","slug":"database-events","link":"#database-events","children":[{"level":3,"title":"Query Logging","slug":"query-logging","link":"#query-logging","children":[]}]}],"relativePath":"2.x/database/basics.md","filePath":"2.x/database/basics.md"}'),u={name:"2.x/database/basics.md"};function d(g,s,h,k,m,b){const o=e("pre-heading"),p=e("post-heading");return i(),l("div",null,[t(o),s[0]||(s[0]=n("h1",null,"Basic Usage",-1)),t(p),s[1]||(s[1]=n("p",null,[a("Connecting to databases and running queries is a simple process, supported by using either raw SQL, the "),n("a",{href:"./../database/query.html"},"query builder"),a(" or "),n("a",{href:"./../database/model.html"},"active record models"),a(". Managing database tables and populating seed data is handled by the "),n("a",{href:"./../database/structure.html"},"migration and seeder process"),a(".")],-1)),s[2]||(s[2]=n("p",null,[a("Raw SQL and using the query builder will perform faster and should be used for simple tasks. Active Record is an approach used by the popular framework, Ruby On Rails. It allows an easy interface for performing repetitive tasks like creating, reading, updating and deleting database records. You can learn more about the "),n("a",{href:"http://en.wikipedia.org/wiki/Active_record_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("active record pattern on Wikipedia"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(".")],-1)),s[3]||(s[3]=r(`<h2 id="configuration"><a href="#configuration" class="header-anchor">#</a> Configuration</h2><p>The database configuration for your application is located in the <code>config/database.php</code> file. In this file you may define all of your database connections, as well as specify which connection should be used by default. Examples for all of the supported database systems are provided in this file.</p><h3 id="read-write-connections"><a href="#read-write-connections" class="header-anchor">#</a> Read / Write Connections</h3><p>Sometimes you may wish to use one database connection for SELECT statements, and another for INSERT, UPDATE, and DELETE statements. It is easy to specify which connection is used whether you are using raw queries, the query builder or a model.</p><p>To see how read / write connections should be configured, let&#39;s look at this example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;read&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;192.168.1.1&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;write&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;196.168.1.2&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mysql&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;database&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;database&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;username&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;root&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;charset&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;collation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8_unicode_ci&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;prefix&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Note that two keys have been added to the configuration array: <code>read</code> and <code>write</code>. Both of these keys have array values containing a single key: <code>host</code>. The rest of the database options for the <code>read</code> and <code>write</code> connections will be merged from the main <code>mysql</code> array.</p><p>We only need to place items in the <code>read</code> and <code>write</code> arrays if we wish to override the values in the main array. So, in this case, <code>192.168.1.1</code> will be used as the &quot;read&quot; connection, while <code>192.168.1.2</code> will be used as the &quot;write&quot; connection. The database credentials, prefix, character set, and all other options in the main <code>mysql</code> array will be shared across both connections.</p><p><a id="oc-running-raw-sql-queries"></a></p><h2 id="running-raw-sql-queries"><a href="#running-raw-sql-queries" class="header-anchor">#</a> Running Raw SQL Queries</h2><p>Once you have configured your database connection, you may run queries using the <code>Db</code> facade. The <code>Db</code> facade provides methods for each type of query: <code>select</code>, <code>update</code>, <code>insert</code>, <code>delete</code>, and <code>statement</code>.</p><h4 id="running-a-select-query"><a href="#running-a-select-query" class="header-anchor">#</a> Running a select query</h4><p>To run a basic query, we can use the <code>select</code> method on the <code>Db</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where active = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The first argument passed to the <code>select</code> method is the raw SQL query, while the second argument is any parameter bindings that need to be bound to the query. Typically, these are the values of the <code>where</code> clause constraints. Parameter binding provides protection against SQL injection.</p><p>The <code>select</code> method will always return an <code>array</code> of results. Each result within the array will be a PHP <code>stdClass</code> object, allowing you to access the values of the results:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="using-named-bindings"><a href="#using-named-bindings" class="header-anchor">#</a> Using named bindings</h4><p>Instead of using <code>?</code> to represent your parameter bindings, you may execute a query using named bindings:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where id = :id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="running-an-insert-statement"><a href="#running-an-insert-statement" class="header-anchor">#</a> Running an insert statement</h4><p>To execute an <code>insert</code> statement, you may use the <code>insert</code> method on the <code>Db</code> facade. Like <code>select</code>, this method takes the raw SQL query as its first argument and bindings as the second argument:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;insert into users (id, name) values (?, ?)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="running-an-update-statement"><a href="#running-an-update-statement" class="header-anchor">#</a> Running an update statement</h4><p>The <code>update</code> method should be used to update existing records in the database. The number of rows affected by the statement will be returned by the method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;update users set votes = 100 where name = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="running-a-delete-statement"><a href="#running-a-delete-statement" class="header-anchor">#</a> Running a delete statement</h4><p>The <code>delete</code> method should be used to delete records from the database. Like <code>update</code>, the number of rows deleted will be returned:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deleted</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;delete from users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="running-a-general-statement"><a href="#running-a-general-statement" class="header-anchor">#</a> Running a general statement</h4><p>Some database statements should not return any value. For these types of operations, you may use the <code>statement</code> method on the <code>Db</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">statement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;drop table users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-multiple-database-connections"></a></p><h2 id="multiple-database-connections"><a href="#multiple-database-connections" class="header-anchor">#</a> Multiple Database Connections</h2><p>When using multiple connections, you may access each connection via the <code>connection</code> method on the <code>Db</code> facade. The <code>name</code> passed to the <code>connection</code> method should correspond to one of the connections listed in your <code>config/database.php</code> configuration file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also access the raw, underlying PDO instance using the <code>getPdo</code> method on a connection instance:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pdo</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getPdo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="database-transactions"><a href="#database-transactions" class="header-anchor">#</a> Database Transactions</h2><p>To run a set of operations within a database transaction, you may use the <code>transaction</code> method on the <code>Db</code> facade. If an exception is thrown within the transaction <code>Closure</code>, the transaction will automatically be rolled back. If the <code>Closure</code> executes successfully, the transaction will automatically be committed. You don&#39;t need to worry about manually rolling back or committing while using the <code>transaction</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">transaction</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="manually-using-transactions"><a href="#manually-using-transactions" class="header-anchor">#</a> Manually using transactions</h4><p>If you would like to begin a transaction manually and have complete control over rollbacks and commits, you may use the <code>beginTransaction</code> method on the <code>Db</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">beginTransaction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can rollback the transaction via the <code>rollBack</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">rollBack</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Lastly, you can commit a transaction via the <code>commit</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: Using the <code>Db</code> facade&#39;s transaction methods also controls transactions for the <a href="./../database/query.html">query builder</a> and <a href="./../database/model.html">model queries</a>.</p></blockquote><h2 id="database-events"><a href="#database-events" class="header-anchor">#</a> Database Events</h2><p>If you would like to receive each SQL query executed by your application, you may use the <code>listen</code> method. This method is useful for logging queries or debugging.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$sql</span><span class="token punctuation">,</span> <span class="token variable">$bindings</span><span class="token punctuation">,</span> <span class="token variable">$time</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Just like <a href="./../services/events.html#oc-where-to-register-listeners">event registration</a>, you may register your query listener in the <code>boot</code> method of a <a href="./../plugin/registration.html#oc-registration-methods">Plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place this logic.</p><h3 id="query-logging"><a href="#query-logging" class="header-anchor">#</a> Query Logging</h3><p>When query logging is enabled, a log is kept in memory of all queries that have been run for the current request. Call the <code>enableQueryLog</code> method to enable this feature.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">enableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To get an array of the executed queries, you may use the <code>getQueryLog</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$queries</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">getQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>However, in some cases, such as when inserting a large number of rows, this can cause the application to use excess memory. To disable the log, you may use the <code>disableQueryLog</code> method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">disableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: For quicker debugging it may be more useful to call the <code>trace_sql</code> <a href="./../services/error-log.html#oc-helper-functions">helper function</a> instead.</p></blockquote>`,61))])}const v=c(u,[["render",d]]);export{y as __pageData,v as default};
